        // двухцветность: тёмные уровни (внутренняя часть, углубления, полосы) — вторым металлом
        if (m2 && def.split) { const st2 = metalStops(m2); out.m = Ls.map((L, i) => sampleStops(i < def.split ? st2 : st, L)); continue; }
