        s += `<circle cx="32" cy="28" r="13" fill="${c.flat(dark, 't2r')}" stroke="${light}" stroke-width="1"/>` + txt(32, 26.5, 'TIER 2', 2.6, light) + txt(32, 32.5, ini, 4.4, '#fff');
