    const spark = (x, y, r) => `<path d="M${x} ${n(y - r)}L${n(x + r * .22)} ${n(y - r * .22)}L${n(x + r)} ${y}L${n(x + r * .22)} ${n(y + r * .22)}L${x} ${n(y + r)}L${n(x - r * .22)} ${n(y + r * .22)}L${n(x - r)} ${y}L${n(x - r * .22)} ${n(y - r * .22)}z" fill="#fff8dc"/>`;
